 @Test void claimCorrectionRequiresIndependentReviewAndPreservesPartialAndFullOriginals(){claimPayment(DAY,"80");var first=correction("CLAIM",payment,"20",DAY,List.of());var pending=call(()->service.request(first));assertThat(pending).containsEntry("status","REVIEW");assertThat(netClaim()).isEqualByComparingTo("80");call(()->service.request(first));assertThatThrownBy(()->call(()->service.review(first.requestId(),new Review(0,true,"不得自审")))).isInstanceOf(AccessDeniedException.class);as(finance,"finance.review");call(()->service.review(first.requestId(),review()));call(()->service.review(first.requestId(),review()));assertThat(netClaim()).isEqualByComparingTo("60");as(cashier,"finance.pay");var second=correction("CLAIM",payment,"60",DAY,List.of());call(()->service.request(second));as(finance,"finance.review");call(()->service.review(second.requestId(),review()));assertThat(netClaim()).isZero();assertThat(jdbc.queryForObject("select amount from finance_payment where id=?",BigDecimal.class,payment)).isEqualByComparingTo("80");assertThat(jdbc.queryForObject("select count(*) from fa_source_event where source_type='FX_CASH_CORRECTION' and hotel_id=?",Integer.class,hotel)).isEqualTo(2);assertThatThrownBy(()->jdbc.update("update fx_cash_correction set amount=1 where id=?",first.requestId())).hasMessageContaining("immutable");}
 @Test void matchedClaimErrorNeedsExplicitImmutableInverseAndOnlyReleasesItsAllocation(){
  claimPayment(DAY,"80");UUID bank=bank(),match=UUID.randomUUID();
  jdbc.update("insert into fc_cash_instruction(id,tenant_id,hotel_id,company_id,source_kind,source_id,source_version,action,amount,occurred_on,bank_account_id,beneficiary_snapshot,bank_snapshot,reference,note,snapshot_hash,status,created_by,reviewer_id,reviewed_by,cashier_id,applicant_id) values(?,?,?,?,'CLAIM',?,2,'PAYMENT',80,?,?,'{}','{}','真实付款流水','已独立审核',?,'EXECUTED',?,?,?,?,?)",request,T,hotel,company,claim,DAY,bank,"0".repeat(64),director,finance,finance,cashier,applicant);
  UUID transaction=transaction(bank,"OUT","80");jdbc.update("insert into fc_claim_bank_match(id,tenant_id,transaction_id,instruction_id,amount,note,created_by) values(?,?,?,?,80,'已核对',?)",match,T,transaction,request,cashier);
  LocalDate matchedOn=jdbc.queryForObject("select (created_at at time zone 'Asia/Shanghai')::date from fc_claim_bank_match where id=?",LocalDate.class,match);
  LocalDate asOf=matchedOn.isAfter(DAY)?matchedOn:DAY;
  assertThatThrownBy(()->call(()->service.request(correction("CLAIM",payment,"20",DAY,List.of())))).hasMessageContaining("明确匹配逆向");
  var input=correction("CLAIM",payment,"20",DAY,List.of(new MatchReverse(match,new BigDecimal("20"))));call(()->service.request(input));as(finance,"finance.review");call(()->service.review(input.requestId(),review()));
  assertThat(jdbc.queryForObject("select amount from fc_claim_bank_match where id=?",BigDecimal.class,match)).isEqualByComparingTo("80");
  assertThat(jdbc.queryForObject("select fx_bank_allocated_amount(?,?,?)",BigDecimal.class,T,transaction,asOf)).isEqualByComparingTo("60");
  assertThat(jdbc.queryForObject("select fx_bank_allocated_amount(?,?,?)",BigDecimal.class,T,transaction,matchedOn.minusDays(1))).isZero();
  assertThatThrownBy(()->jdbc.update("delete from fx_bank_match_reversal where match_id=?",match)).hasMessageContaining("append-only");
 }
