 @Test void closedOriginalPeriodUsesOpenCorrectionDateAndDoesNotRestateHistoricalCash(){LocalDate old=DAY.minusMonths(1);claimPayment(old,"80");UUID book=UUID.randomUUID();as(finance,"*");call(()->accounting.createBook(new FinanceAccountingModels.Book(book,hotel,company,"真实账簿",old.withDayOfMonth(1))));jdbc.update("insert into fa_period(tenant_id,book_id,month,status) values(?,?,?,'CLOSED')",T,book,old.withDayOfMonth(1));as(cashier,"finance.pay");assertThatThrownBy(()->call(()->service.request(correction("CLAIM",payment,"20",old,List.of())))).hasMessageContaining("已锁定");var input=correction("CLAIM",payment,"20",DAY,List.of());call(()->service.request(input));as(finance,"finance.review");call(()->service.review(input.requestId(),review()));assertThat(jdbc.queryForObject("select fx_claim_paid_amount(?,?,?)",BigDecimal.class,T,claim,old)).isEqualByComparingTo("80");assertThat(netClaim()).isEqualByComparingTo("60");assertThat(jdbc.queryForMap("select original_date,accounting_on from fx_cash_correction where id=?",input.requestId())).containsEntry("original_date",java.sql.Date.valueOf(old)).containsEntry("accounting_on",java.sql.Date.valueOf(DAY));}
